// Grab the current pairing QR URL text from the page (already generated by qa-110-verify-a.mjs).
import { open } from './app.mjs';
const app = await open('devices');
await app.page.waitForTimeout(500);
const url = await app.page.locator('code').first().innerText().catch(() => null);
console.log('QR_URL:', url);
await app.done();
